 "content": "def transform(grid):
    out = [row[:] for row in grid]
    # The matching-color marks at the top and bottom identify columns to
    # connect vertically, stopping at the full-width 2 divider.
    if not grid:
        return out
    width = len(grid[0])
    divider = next((r for r, row in enumerate(grid) if len(row) == width and all(v == 2 for v in row)), None)
    if divider is None:
        return out
    top = next((r for r, row in enumerate(grid[:divider]) if any(v != 0 for v in row)), None)
    bottom = next((r for r, row in enumerate(grid[divider + 1:], divider + 1) if any(v != 0 for v in row)), None)
    if top is None or bottom is None:
        return out
    color = next((v for v in grid[top] if v != 0), None)
    if color is None:
        return out
    cols = [c for c in range(width) if grid[top][c] == color and grid[bottom][c] == color]
    for c in cols:
        for r in range(top + 1, divider):
            if out[r][c] == 0:
                out[r][c] = 4
    return out

